const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const { spawn, spawnSync } = require('child_process');

// PLAN MAISON 3D — serveur autonome et robuste.
// Le HTML et le script Blender sont embarqués. Le rendu est asynchrone
// pour éviter les 502 lorsque Blender prend plusieurs dizaines de secondes.
const APP = __dirname;
const PUBLIC = path.join(APP, 'public');
const BLENDER_DIR = path.join(APP, 'blender');
const RENDERS = path.join(APP, 'renders');
const JOBS = new Map();
const PORT = Number(process.env.PORT || 3000);
const BLENDER = process.env.BLENDER_BIN || 'blender';
const MAX_RENDER_MS = Number(process.env.RENDER_TIMEOUT_MS || 150000);
const HTML_B64 = '';
const BLENDER_B64 = '';

fs.mkdirSync(PUBLIC, {recursive:true});
fs.mkdirSync(BLENDER_DIR, {recursive:true});
fs.mkdirSync(RENDERS, {recursive:true});

function writeEmbeddedFiles() {
  const htmlPath=path.join(PUBLIC,'index.html');
  const blenderPath=path.join(BLENDER_DIR,'render_plan.py');
  const html=Buffer.from(HTML_B64,'base64');
  const blender=Buffer.from(BLENDER_B64,'base64');
  if(!fs.existsSync(htmlPath) || fs.statSync(htmlPath).size!==html.length) fs.writeFileSync(htmlPath,html);
  if(!fs.existsSync(blenderPath) || fs.statSync(blenderPath).size!==blender.length) fs.writeFileSync(blenderPath,blender);
}
writeEmbeddedFiles();

const app=express();
app.use(express.json({limit:'2mb'}));
app.use(express.static(PUBLIC));
app.use('/renders',express.static(RENDERS,{maxAge:'1h',fallthrough:false}));

let blenderInfo='non vérifié';
try {
  const p=spawnSync(BLENDER,['--background','--version'],{encoding:'utf8',timeout:12000});
  blenderInfo=((p.stdout||p.stderr||'').trim().split('\n')[0]) || ('code '+p.status);
} catch(e) { blenderInfo='indisponible: '+e.message; }
console.log('PLAN MAISON 3D — Blender:', blenderInfo);

app.get('/api/health',(req,res)=>res.json({ok:true,service:'PLAN MAISON 3D',blender:BLENDER,blenderInfo,autonomous:true}));

function validate(payload) {
  if(!payload || !payload.plan || !Array.isArray(payload.plan.rooms)) throw new Error('Plan structuré manquant.');
  const L=Number(payload.plan.terrain?.length_m), W=Number(payload.plan.terrain?.width_m);
  if(!Number.isFinite(L)||!Number.isFinite(W)||L<6||W<8||L>100||W>100) throw new Error('Dimensions du terrain invalides.');
  if(payload.plan.rooms.length>100||(payload.plan.doors||[]).length>300||(payload.plan.windows||[]).length>300) throw new Error('Plan trop volumineux.');
}

function launchJob(id,outFile,payloadFile) {
  const script=path.join(BLENDER_DIR,'render_plan.py');
  const args=['--background','--factory-startup','-P',script,'--','--payload-file',payloadFile,'--output',outFile];
  const child=spawn(BLENDER,args,{cwd:APP,env:{...process.env,HOME:'/tmp/plan-maison-home',XDG_CONFIG_HOME:'/tmp/plan-maison-config'},stdio:['ignore','pipe','pipe']});
  let stdout='',stderr='';
  JOBS.set(id,{status:'processing',startedAt:Date.now()});
  child.stdout.on('data',d=>{stdout+=d.toString(); if(stdout.length>6000)stdout=stdout.slice(-6000);});
  child.stderr.on('data',d=>{stderr+=d.toString(); if(stderr.length>10000)stderr=stderr.slice(-10000);});
  const timer=setTimeout(()=>{
    try{child.kill('SIGKILL')}catch{}
    JOBS.set(id,{status:'error',error:'Blender a dépassé le délai de '+Math.round(MAX_RENDER_MS/1000)+' secondes.',log:(stderr||stdout).slice(-2500)});
    try{fs.unlinkSync(payloadFile)}catch{}
  },MAX_RENDER_MS);
  child.on('error',err=>{clearTimeout(timer); JOBS.set(id,{status:'error',error:'Impossible de lancer Blender: '+err.message,log:(stderr||stdout).slice(-2500)}); try{fs.unlinkSync(payloadFile)}catch{};});
  child.on('close',(code,signal)=>{
    clearTimeout(timer);
    try{fs.unlinkSync(payloadFile)}catch{}
    if(code===0 && fs.existsSync(outFile)) JOBS.set(id,{status:'done',image_url:'/renders/'+id+'.png',finishedAt:Date.now()});
    else if(!JOBS.get(id) || JOBS.get(id).status!=='error') JOBS.set(id,{status:'error',error:'Blender a échoué (code '+code+', signal '+(signal||'aucun')+').',log:(stderr||stdout).slice(-3500)});
  });
}

app.post('/api/render3d',(req,res)=>{
  try {
    const payload=req.body||{}; validate(payload);
    const id=crypto.randomUUID();
    const outFile=path.join(RENDERS,id+'.png');
    const payloadFile=path.join(RENDERS,id+'.json');
    fs.writeFileSync(payloadFile,JSON.stringify(payload));
    launchJob(id,outFile,payloadFile);
    res.status(202).json({ok:true,status:'processing',id,message:'Rendu Blender lancé.'});
  } catch(e) { res.status(400).json({ok:false,error:e.message||'Requête invalide'}); }
});

app.get('/api/render3d/status/:id',(req,res)=>{
  const id=String(req.params.id||'');
  const j=JOBS.get(id);
  if(!j) return res.status(404).json({ok:false,status:'not_found',error:'Rendu introuvable ou serveur redémarré.'});
  res.json({ok:j.status==='done',...j});
});

setInterval(()=>{
  const cutoff=Date.now()-6*60*60*1000;
  for(const [id,j] of JOBS) if((j.finishedAt||j.startedAt||0)<cutoff) JOBS.delete(id);
  try{for(const f of fs.readdirSync(RENDERS)){const p=path.join(RENDERS,f); if(fs.statSync(p).mtimeMs<cutoff) fs.unlinkSync(p);}}catch{}
},30*60*1000).unref();

app.get('*',(req,res)=>res.sendFile(path.join(PUBLIC,'index.html')));
app.listen(PORT,()=>console.log('PLAN MAISON 3D listening on '+PORT));
